47:func Range(ctx context.Context, lg *zap.Logger, kv mvcc.KV, r *pb.RangeRequest, withTotalCount bool) (resp *pb.RangeResponse, trace *traceutil.Trace, err error) {
48:	ctx, trace = traceutil.EnsureTrace(ctx, lg, "range")
49:	defer func(start time.Time) {
