59:func executeRange(ctx context.Context, lg *zap.Logger, txnRead mvcc.TxnRead, r *pb.RangeRequest, withTotalCount bool) (*pb.RangeResponse, error) {
60:	trace := traceutil.Get(ctx)
61:
62:	limit := rangeLimit(r)
63:	ro := mvcc.RangeOptions{
64:		Limit:          limit,
65:		Rev:            r.Revision,
66:		CountOnly:      r.CountOnly,
67:		FastKeysOnly:   r.KeysOnly && r.SortTarget != pb.RangeRequest_VALUE,
68:		WithTotalCount: withTotalCount,
69:	}
70:
71:	rr, err := txnRead.Range(ctx, r.Key, mkGteRange(r.RangeEnd), ro)
72:	if err != nil {
73:		return nil, err
74:	}
75:
76:	filterRangeResults(rr, r)
77:	sortRangeResults(rr, r, lg)
78:	trace.Step("filter and sort the key-value pairs")
79:
80:	resp := asembleRangeResponse(rr, r)
81:	trace.Step("assemble the response")
82:
83:	return resp, nil
84:}
