86:func rangeLimit(r *pb.RangeRequest) int64 {
87:	limit := r.Limit
88:	if !IsDefaultOrdering(r.SortTarget, r.SortOrder) || HasRevisionFilters(r) {
89:		limit = 0
90:	}
91:	if limit > 0 && limit < math.MaxInt64 {
92:		limit = limit + 1
93:	}
94:	return limit
95:}
