97:func IsDefaultOrdering(sortTarget pb.RangeRequest_SortTarget, sortOrder pb.RangeRequest_SortOrder) bool {
98:	// Since current mvcc.Range implementation returns results
99:	// sorted by keys in lexiographically ascending order,
100:	// don't re-sort when target is 'KEY' and order is ASCEND
101:	return sortOrder == pb.RangeRequest_NONE ||
102:		(sortTarget == pb.RangeRequest_KEY && sortOrder == pb.RangeRequest_ASCEND)
103:}
104:
105:func HasRevisionFilters(r *pb.RangeRequest) bool {
106:	return r.MinModRevision != 0 || r.MaxModRevision != 0 ||
107:		r.MinCreateRevision != 0 || r.MaxCreateRevision != 0
108:}
109:
110:func filterRangeResults(rr *mvcc.RangeResult, r *pb.RangeRequest) {
111:	if r.MaxModRevision != 0 {
112:		pruneKVs(rr, func(kv *mvccpb.KeyValue) bool { return kv.ModRevision > r.MaxModRevision })
113:	}
114:	if r.MinModRevision != 0 {
115:		pruneKVs(rr, func(kv *mvccpb.KeyValue) bool { return kv.ModRevision < r.MinModRevision })
116:	}
117:	if r.MaxCreateRevision != 0 {
118:		pruneKVs(rr, func(kv *mvccpb.KeyValue) bool { return kv.CreateRevision > r.MaxCreateRevision })
119:	}
120:	if r.MinCreateRevision != 0 {
121:		pruneKVs(rr, func(kv *mvccpb.KeyValue) bool { return kv.CreateRevision < r.MinCreateRevision })
122:	}
123:}
124:
125:func sortRangeResults(rr *mvcc.RangeResult, r *pb.RangeRequest, lg *zap.Logger) {
126:	sortOrder := r.SortOrder
127:	if r.SortTarget != pb.RangeRequest_KEY && sortOrder == pb.RangeRequest_NONE {
128:		sortOrder = pb.RangeRequest_ASCEND
129:	}
130:
131:	if !IsDefaultOrdering(r.SortTarget, sortOrder) {
132:		var sorter sort.Interface
133:		switch {
134:		case r.SortTarget == pb.RangeRequest_KEY:
135:			sorter = &kvSortByKey{&kvSort{rr.KVs}}
136:		case r.SortTarget == pb.RangeRequest_VERSION:
137:			sorter = &kvSortByVersion{&kvSort{rr.KVs}}
138:		case r.SortTarget == pb.RangeRequest_CREATE:
139:			sorter = &kvSortByCreate{&kvSort{rr.KVs}}
140:		case r.SortTarget == pb.RangeRequest_MOD:
141:			sorter = &kvSortByMod{&kvSort{rr.KVs}}
142:		case r.SortTarget == pb.RangeRequest_VALUE:
143:			sorter = &kvSortByValue{&kvSort{rr.KVs}}
144:		default:
145:			lg.Panic("unexpected sort target", zap.Int32("sort-target", int32(r.SortTarget)))
146:		}
147:		switch {
148:		case sortOrder == pb.RangeRequest_ASCEND:
149:			sort.Sort(sorter)
150:		case sortOrder == pb.RangeRequest_DESCEND:
151:			sort.Sort(sort.Reverse(sorter))
152:		}
153:	}
154:}
