156:func asembleRangeResponse(rr *mvcc.RangeResult, r *pb.RangeRequest) *pb.RangeResponse {
157:	resp := &pb.RangeResponse{Header: &pb.ResponseHeader{}}
158:	if r.Limit > 0 && len(rr.KVs) > int(r.Limit) {
159:		rr.KVs = rr.KVs[:r.Limit]
160:		resp.More = true
161:	}
162:	resp.Header.Revision = rr.Rev
163:	resp.Count = int64(rr.Count)
164:	resp.Kvs = make([]*mvccpb.KeyValue, len(rr.KVs))
165:	for i := range rr.KVs {
166:		if r.KeysOnly {
167:			rr.KVs[i].Value = nil
168:		}
169:		resp.Kvs[i] = rr.KVs[i]
170:	}
171:	return resp
172:}
