174:func checkRange(rv mvcc.ReadView, req *pb.RangeRequest) error {
175:	switch {
176:	case req.Revision == 0:
177:		return nil
178:	case req.Revision > rv.Rev():
179:		return mvcc.ErrFutureRev
180:	case req.Revision < rv.FirstRev():
181:		return mvcc.ErrCompacted
182:	}
183:	return nil
184:}
