186:func pruneKVs(rr *mvcc.RangeResult, isPrunable func(*mvccpb.KeyValue) bool) {
187:	j := 0
188:	for i := range rr.KVs {
189:		rr.KVs[j] = rr.KVs[i]
190:		if !isPrunable(rr.KVs[i]) {
191:			j++
192:		}
193:	}
194:	rr.KVs = rr.KVs[:j]
195:}
