106:func (s *EtcdServer) Range(ctx context.Context, r *pb.RangeRequest) (*pb.RangeResponse, error) {
107:	var span trace.Span
108:	ctx, span = traceutil.Tracer.Start(ctx, "range", trace.WithAttributes(
109:		attribute.String("range_begin", string(r.GetKey())),
110:		attribute.String("range_end", string(r.GetRangeEnd())),
111:		attribute.Int64("rev", r.GetRevision()),
112:		attribute.Int64("limit", r.GetLimit()),
113:		attribute.Bool("count_only", r.GetCountOnly()),
114:		attribute.Bool("keys_only", r.GetKeysOnly()),
115:	))
116:	defer span.End()
117:
118:	ctx, trace := traceutil.EnsureTrace(ctx, s.Logger(), "range",
119:		traceutil.Field{Key: "range_begin", Value: string(r.Key)},
120:		traceutil.Field{Key: "range_end", Value: string(r.RangeEnd)},
121:	)
122:
123:	var resp *pb.RangeResponse
124:	var err error
125:	defer func(start time.Time) {
126:		txn.WarnOfExpensiveReadOnlyRangeRequest(s.Logger(), s.Cfg.WarningApplyDuration, start, r, resp, err)
127:		if resp != nil {
128:			trace.AddField(
129:				traceutil.Field{Key: "response_count", Value: len(resp.Kvs)},
130:				traceutil.Field{Key: "response_revision", Value: resp.Header.Revision},
131:			)
132:		}
133:		trace.LogIfLong(traceThreshold)
134:		success := err == nil
135:		requestDurationSec.WithLabelValues("Range", strconv.FormatBool(success)).Observe(time.Since(start).Seconds())
136:	}(time.Now())
137:
138:	if !r.Serializable {
139:		err = s.read.LinearizableReadNotify(ctx)
140:		trace.Step("agreement among raft nodes before linearized reading")
141:		if err != nil {
142:			return nil, err
143:		}
144:	}
145:	chk := func(ai *auth.AuthInfo) error {
146:		return s.authStore.IsRangePermitted(ai, r.Key, r.RangeEnd)
147:	}
148:
149:	get := func() { resp, _, err = txn.Range(ctx, s.Logger(), s.KV(), r, true) }
150:	if serr := s.doSerialize(ctx, chk, get); serr != nil {
151:		err = serr
152:		return nil, err
153:	}
154:	return resp, err
155:}
